import{_ as r,C as o,o as a,c as s,a2 as t,b as i,w as d,a as l,E as b,a3 as h}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Bandwidth Monitor for Pterodactyl","description":"Per-server bandwidth monitoring and enforcement for Pterodactyl — tc speed caps, day/week/month quotas, quota-driven throttle and suspend, all managed from the panel.","frontmatter":{"title":"Bandwidth Monitor for Pterodactyl","description":"Per-server bandwidth monitoring and enforcement for Pterodactyl — tc speed caps, day/week/month quotas, quota-driven throttle and suspend, all managed from the panel.","head":[["meta",{"name":"og:title","content":"Bandwidth Monitor for Pterodactyl — Panel-Native Traffic Control"}],["meta",{"name":"og:description","content":"A Blueprint panel addon plus a Go node agent that gives every game server speed caps, multi-period quotas, reports and predictions — enforced with tc on each Wings node."}]]},"headers":[],"relativePath":"pterodactyl-bandwidth-monitor/index.md","filePath":"pterodactyl-bandwidth-monitor/index.md","lastUpdated":1787470737000}'),c={name:"pterodactyl-bandwidth-monitor/index.md"};function p(v,e,g,u,m,y){const n=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="bandwidth-monitor-for-pterodactyl" tabindex="-1" data-v-e85b7d5a>Bandwidth Monitor for Pterodactyl <a class="header-anchor" href="#bandwidth-monitor-for-pterodactyl" aria-label="Permalink to &quot;Bandwidth Monitor for Pterodactyl&quot;" data-v-e85b7d5a>​</a></h1><p data-v-e85b7d5a><strong data-v-e85b7d5a>Panel-native bandwidth monitoring and enforcement for Pterodactyl</strong> — a Blueprint addon on the panel plus a Go agent (<code data-v-e85b7d5a>bandwidth-noded</code>) on every Wings node. It counts inbound/outbound traffic per game server, enforces per-server speed caps and day/week/month quotas with Linux <code data-v-e85b7d5a>tc</code>, and surfaces dashboards, reports and usage predictions directly in your admin area.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-e85b7d5a><p data-v-e85b7d5a><strong data-v-e85b7d5a>📡 Built for ALTIS TECH SOLUTIONS</strong><br data-v-e85b7d5a><a href="https://xdp.network" target="_blank" rel="noreferrer" data-v-e85b7d5a>xdp.network</a> · Panel addon + node agent, installed separately</p></div><hr data-v-e85b7d5a><h2 id="architecture" tabindex="-1" data-v-e85b7d5a>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-e85b7d5a>​</a></h2>',5)),(a(),i(h,null,{default:d(()=>[b(n,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%22%5D%0A%20%20%20%20%20%20%20%20ADDON%5B%22Bandwidth%20Monitor%20addon%3Cbr%2F%3E(Blueprint%3A%20pterodactylbandwidth)%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(%22bandwidth_*%20tables%3Cbr%2F%3Etokens%20%C2%B7%20limits%20%C2%B7%20events%20%C2%B7%20rollups%22)%5D%0A%20%20%20%20%20%20%20%20UI%5B%22Admin%20UI%3Cbr%2F%3EDashboard%20%C2%B7%20Nodes%20%C2%B7%20Servers%20%C2%B7%20Reports%20%C2%B7%20Events%20%C2%B7%20Settings%22%5D%0A%20%20%20%20%20%20%20%20ADDON%20--%3E%20DB%0A%20%20%20%20%20%20%20%20UI%20--%3E%20ADDON%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node1%5B%22Wings%20Node%201%22%5D%0A%20%20%20%20%20%20%20%20AGENT1%5B%22bandwidth-noded%22%5D%0A%20%20%20%20%20%20%20%20TC1%5B%22tc%20(HTB%20%2B%20ingress%20police)%22%5D%0A%20%20%20%20%20%20%20%20C1%5B%22Server%20containers%22%5D%0A%20%20%20%20%20%20%20%20AGENT1%20--%3E%20TC1%20--%3E%20C1%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Node2%5B%22Wings%20Node%202%22%5D%0A%20%20%20%20%20%20%20%20AGENT2%5B%22bandwidth-noded%22%5D%0A%20%20%20%20%20%20%20%20TC2%5B%22tc%20(HTB%20%2B%20ingress%20police)%22%5D%0A%20%20%20%20%20%20%20%20C2%5B%22Server%20containers%22%5D%0A%20%20%20%20%20%20%20%20AGENT2%20--%3E%20TC2%20--%3E%20C2%0A%20%20%20%20end%0A%0A%20%20%20%20AGENT1%20--%3E%7C%22register%20(one-time%20pairing)%22%7C%20ADDON%0A%20%20%20%20AGENT1%20--%3E%7C%22heartbeat%20every%2060s%22%7C%20ADDON%0A%20%20%20%20AGENT1%20--%3E%7C%22events%20%2B%20suspend%20callbacks%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22limits%20push%20(PUT%20%2Flimits)%22%7C%20AGENT1%0A%20%20%20%20ADDON%20--%3E%7C%22stats%20%2B%20history%20pulls%22%7C%20AGENT1%0A%20%20%20%20AGENT2%20--%3E%7C%22register%20%C2%B7%20heartbeat%20%C2%B7%20events%22%7C%20ADDON%0A%20%20%20%20ADDON%20--%3E%7C%22limits%20push%20%C2%B7%20stats%20pulls%22%7C%20AGENT2%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p data-v-e85b7d5a>The node agent authenticates to the panel with a per-node 64-hex bearer token; the panel uses the same token when calling back into the node. The wire protocol on both sides is a single documented API contract with a <code data-v-e85b7d5a>{success, data, error, meta}</code> envelope everywhere.</p><hr data-v-e85b7d5a><h2 id="key-features" tabindex="-1" data-v-e85b7d5a>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-e85b7d5a>​</a></h2><ul data-v-e85b7d5a><li data-v-e85b7d5a><strong data-v-e85b7d5a>🚦 Per-server speed caps (RX and TX).</strong> Set inbound and outbound Mbps limits per server. Enforced on each container&#39;s veth with <code data-v-e85b7d5a>tc</code> HTB for egress and an ingress qdisc with policing for RX — kernel-level, no userspace throttling.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>📅 Day / week / month quotas, per direction.</strong> Independent RX and TX quotas for each period, in GiB. Periods reset at calendar boundaries (midnight, Monday 00:00, 1st 00:00) in a configurable timezone.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>⚖️ Configurable exceed actions.</strong> When a quota trips, the node applies the server&#39;s action: <strong data-v-e85b7d5a>throttle</strong> (re-apply <code data-v-e85b7d5a>tc</code> at low throttle speeds), <strong data-v-e85b7d5a>suspend</strong> (panel callback suspends the Pterodactyl server, then throttle to 1 Mbps), or <strong data-v-e85b7d5a>log-only</strong> (event recorded, no enforcement).</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>🔑 Per-node pairing tokens.</strong> Every Pterodactyl node gets a 64-hex pairing token on the Nodes page — viewable and resettable from the UI. Resetting a token kills the old one immediately.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>🖥️ Native admin UI.</strong> Seven AdminLTE pages inside your panel — Dashboard, a full <strong data-v-e85b7d5a>Analytics</strong> tab (period comparisons, per-node/per-user consumption, quota watch, projections), Nodes, Servers, Reports, Events, Settings — with bundled Chart.js served from <code data-v-e85b7d5a>public/ext/</code> (build-proof), and searchable, sortable, paginated tables throughout.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>📈 Hourly + daily rollups.</strong> The panel polls each online node for counters every minute and stores per-server hourly and daily usage buckets for fast charting and reporting.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>🔮 Usage predictions.</strong> Linear projection per server (current usage + average rate × remaining time, cross-checked against the 7-day daily average) surfaces &quot;projected to exceed quota on &lt;date&gt;&quot; before it happens.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>📄 Reports with CSV export.</strong> Date-ranged per-server usage reports, downloadable as CSV for billing or finance tooling.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>🧩 Server build-config integration.</strong> Bandwidth fields (enabled, speed caps, six quota fields, exceed action, throttle speeds) are added directly to the server build configuration, with admin defaults from <strong data-v-e85b7d5a>Settings</strong> prefilling every new server.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>🏷️ Optional quota-suspension tagging.</strong> Servers suspended for exceeding a quota can be renamed to <code data-v-e85b7d5a>(Bandwidth Quota Exceeded) &lt;name&gt;</code> until they&#39;re unsuspended — manually, on period reset, or via Unthrottle. Servers suspended by anything else are never touched.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>🔀 Lifecycle-aware.</strong> Server deletion cascades limits/usage cleanly (events kept as an audit trail); transfers push the fresh limits to both the old and new node so caps follow the server instantly.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>💾 Crash-safe enforcement.</strong> Counters, limits and the outbound event queue persist in SQLite on the node; <code data-v-e85b7d5a>tc</code> rules are re-applied on boot, so enforcement survives agent restarts.</li></ul><hr data-v-e85b7d5a><h2 id="quick-install" tabindex="-1" data-v-e85b7d5a>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-e85b7d5a>​</a></h2><p data-v-e85b7d5a>Both halves are installed separately. Panel first, then each node.</p><p data-v-e85b7d5a><strong data-v-e85b7d5a>Panel (Blueprint):</strong></p><div class="language-bash vp-adaptive-theme" data-v-e85b7d5a><button title="Copy Code" class="copy" data-v-e85b7d5a></button><span class="lang" data-v-e85b7d5a>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-e85b7d5a><code data-v-e85b7d5a><span class="line" data-v-e85b7d5a><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-e85b7d5a># place pterodactylbandwidth-v1.0.0.blueprint in /var/www/pterodactyl, then:</span></span>
<span class="line" data-v-e85b7d5a><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-e85b7d5a>blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-e85b7d5a> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-e85b7d5a> pterodactylbandwidth-v1.0.0</span></span></code></pre></div><p data-v-e85b7d5a><strong data-v-e85b7d5a>Each Wings node (as root):</strong></p><div class="language-bash vp-adaptive-theme" data-v-e85b7d5a><button title="Copy Code" class="copy" data-v-e85b7d5a></button><span class="lang" data-v-e85b7d5a>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-e85b7d5a><code data-v-e85b7d5a><span class="line" data-v-e85b7d5a><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-e85b7d5a>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-e85b7d5a> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-e85b7d5a> install.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-e85b7d5a>   # from the node-module directory — prompts for panel URL + node token</span></span></code></pre></div><p data-v-e85b7d5a>Head to the <a href="./getting-started/quick-start" data-v-e85b7d5a>Quick Start</a> for the full ten-minute walkthrough with expected output.</p><hr data-v-e85b7d5a><h2 id="how-pairing-works" tabindex="-1" data-v-e85b7d5a>How Pairing Works <a class="header-anchor" href="#how-pairing-works" aria-label="Permalink to &quot;How Pairing Works&quot;" data-v-e85b7d5a>​</a></h2><ol data-v-e85b7d5a><li data-v-e85b7d5a><strong data-v-e85b7d5a>Token issued.</strong> Open <strong data-v-e85b7d5a>Admin → Bandwidth → Nodes</strong>. Every Pterodactyl node gets a row with a generated 64-hex token. The panel stores a bcrypt hash for verification plus an encrypted copy so you can re-view (or reset) it later.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>Node installed.</strong> Run <code data-v-e85b7d5a>node-module/install.sh</code> as root on the Wings node. It prompts for the panel URL and token, writes <code data-v-e85b7d5a>/etc/bandwidth-node/config.yaml</code> and <code data-v-e85b7d5a>/etc/bandwidth-node/token</code> (both <code data-v-e85b7d5a>0600</code>), and starts the <code data-v-e85b7d5a>bandwidth-node</code> systemd service.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>Node registers.</strong> The agent calls <code data-v-e85b7d5a>POST /api/bandwidth/node/register</code> (retrying with backoff). The panel verifies the bearer token, records the node&#39;s reachable API URL, and flips the node to <strong data-v-e85b7d5a>online</strong> in the UI.</li><li data-v-e85b7d5a><strong data-v-e85b7d5a>Steady state.</strong> The node heartbeats every 60 s with aggregate stats. When limits change in the panel, the heartbeat response carries a bumped <code data-v-e85b7d5a>config_version</code> and the node pulls and re-applies them; the panel pushes full limit sets and pulls per-server stats and history in return.</li></ol><hr data-v-e85b7d5a><h2 id="comparison-with-bandwidth-manager" tabindex="-1" data-v-e85b7d5a>Comparison with Bandwidth Manager <a class="header-anchor" href="#comparison-with-bandwidth-manager" aria-label="Permalink to &quot;Comparison with Bandwidth Manager&quot;" data-v-e85b7d5a>​</a></h2><p data-v-e85b7d5a>Bandwidth Monitor builds on the same <code data-v-e85b7d5a>tc</code>-enforcement philosophy as our standalone <a href="/pingless-studios-docs/bandwidth-manager/" data-v-e85b7d5a>Bandwidth Manager</a> project, but is purpose-built for Pterodactyl panels.</p><table tabindex="0" data-v-e85b7d5a><thead data-v-e85b7d5a><tr data-v-e85b7d5a><th data-v-e85b7d5a>Capability</th><th style="text-align:center;" data-v-e85b7d5a>Bandwidth Monitor for Pterodactyl</th><th style="text-align:center;" data-v-e85b7d5a>Bandwidth Manager (standalone)</th></tr></thead><tbody data-v-e85b7d5a><tr data-v-e85b7d5a><td data-v-e85b7d5a>Pterodactyl server ↔ container mapping</td><td style="text-align:center;" data-v-e85b7d5a>✅ native (UUID containers)</td><td style="text-align:center;" data-v-e85b7d5a>❌ generic Docker labels</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Central multi-node admin UI</td><td style="text-align:center;" data-v-e85b7d5a>✅ panel pages + dashboards</td><td style="text-align:center;" data-v-e85b7d5a>❌ per-host CLI/TUI</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Quota periods</td><td style="text-align:center;" data-v-e85b7d5a>✅ day / week / month</td><td style="text-align:center;" data-v-e85b7d5a>✅ daily</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Quotas per direction (RX + TX separately)</td><td style="text-align:center;" data-v-e85b7d5a>✅</td><td style="text-align:center;" data-v-e85b7d5a>❌</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Usage predictions</td><td style="text-align:center;" data-v-e85b7d5a>✅</td><td style="text-align:center;" data-v-e85b7d5a>❌</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Suspend server on exceed</td><td style="text-align:center;" data-v-e85b7d5a>✅ via panel API</td><td style="text-align:center;" data-v-e85b7d5a>❌ (throttle only)</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Reports + CSV export</td><td style="text-align:center;" data-v-e85b7d5a>✅</td><td style="text-align:center;" data-v-e85b7d5a>✅ CSV export</td></tr><tr data-v-e85b7d5a><td data-v-e85b7d5a>Multi-node from one screen</td><td style="text-align:center;" data-v-e85b7d5a>✅</td><td style="text-align:center;" data-v-e85b7d5a>❌</td></tr></tbody></table><blockquote data-v-e85b7d5a><p data-v-e85b7d5a><strong data-v-e85b7d5a>Bottom line:</strong> running a Pterodactyl fleet? Use Bandwidth Monitor — the panel is your single control plane. Running standalone Docker hosts? Bandwidth Manager is the lighter fit.</p></blockquote><hr data-v-e85b7d5a><div class="tip custom-block" data-v-e85b7d5a><p class="custom-block-title" data-v-e85b7d5a>VERIFIED LIVE</p><p data-v-e85b7d5a>Both halves were verified end-to-end on a real Pterodactyl panel and Wings node: pairing and registration, live stats flow into the dashboard, a 10 Mbps cap holding a live server at ~9.5 Mbps, a 1 GiB quota exceed triggering a throttle to 5 Mbps with panel events, a weekly quota exceed suspending the server for real, and an admin unthrottle restoring full speed.</p></div><hr data-v-e85b7d5a><h2 id="next-steps" tabindex="-1" data-v-e85b7d5a>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-e85b7d5a>​</a></h2><ul data-v-e85b7d5a><li data-v-e85b7d5a><strong data-v-e85b7d5a><a href="./getting-started/quick-start" data-v-e85b7d5a>Quick Start →</a></strong> — From archive to enforced speed cap in ten minutes.</li></ul><hr data-v-e85b7d5a><div class="footer-note" data-v-e85b7d5a><p data-v-e85b7d5a><strong data-v-e85b7d5a>Developed for <a href="https://xdp.network" target="_blank" rel="noreferrer" data-v-e85b7d5a>ALTIS TECH SOLUTIONS</a></strong></p><p data-v-e85b7d5a>Questions or licensing — reach us at <a href="https://xdp.network" target="_blank" rel="noreferrer" data-v-e85b7d5a>xdp.network</a>.</p></div>`,27))])}const w=r(c,[["render",p],["__scopeId","data-v-e85b7d5a"]]);export{k as __pageData,w as default};
